import os

targets = {'envelope.json', 'sales_data.csv'}
found = []
for root, dirs, files in os.walk('/', topdown=True):
    # skip noisy system dirs
    dirs[:] = [d for d in dirs if d not in {'proc','sys','dev','run'}]
    for f in files:
        if f in targets:
            found.append(os.path.join(root, f))

print("Matches found:", found if found else "NONE")
